#!/usr/bin/env python3
"""Generate the model's JSON Schema, runtime catalog and compact reference.

Use Python 3.11 and install requirements.lock in an isolated environment first.
--check compares generated bytes without changing the working tree. Generation
uses only local files and installed packages; the shipped CLI embeds its outputs.
"""

from __future__ import annotations

import argparse
import hashlib
from importlib import metadata
import json
from pathlib import Path
import subprocess
import sys
from typing import Any

from relationships import validate_relationships, relationships_markdown
from model_views import validate_declared_memberships, validate_groups, subset_navigation, core_markdown

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent.parent
MODEL = ROOT / "model/dotspec.yaml"
LOCK = HERE / "requirements.lock"


def verify_toolchain() -> None:
    """Refuse unpinned generators rather than silently refreshing projections."""
    if sys.version_info[:2] != (3, 11):
        raise RuntimeError("model generation requires Python 3.11; use the pinned generation environment")
    mismatches = []
    for line in LOCK.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        package, expected = line.split("==", 1)
        try:
            actual = metadata.version(package)
        except metadata.PackageNotFoundError:
            actual = "not installed"
        if actual != expected:
            mismatches.append(f"{package}: expected {expected}, found {actual}")
    if mismatches:
        raise RuntimeError(
            "generation environment does not match scripts/generate-model/requirements.lock:\n"
            + "\n".join(mismatches)
            + "\nInstall the lock in an isolated Python 3.11 environment."
        )


def annotation_values(annotations: Any) -> dict[str, str]:
    from jsonasobj2 import as_dict

    return {str(name): str(item["value"] if isinstance(item, dict) else item.value) for name, item in sorted(as_dict(annotations).items())}


def make_catalog(view: Any, raw_model: dict[str, Any], model_bytes: bytes) -> dict[str, Any]:
    """Project induced LinkML slots without losing inherited/narrowed ranges.

    ancestors includes the class itself. reference_ranges lists allowed class
    ranges only for identifier references; inline_ranges lists class ranges for
    recursive embedded values. any_of narrows range when it is present.
    """
    validate_declared_memberships(raw_model)
    classes = view.all_classes()
    enums = view.all_enums()
    result: dict[str, Any] = {
        "catalog_version": 1,
        "schema_id": str(view.schema.id),
        "model_version": str(view.schema.version),
        "representation_version": view.induced_slot("representation_version", "Snapshot").equals_string,
        "source_sha256": hashlib.sha256(model_bytes).hexdigest(),
        "annotations": annotation_values(view.schema.annotations),
        "subsets": {str(n): {"title": g.title or str(n), "description": g.description or "",
                                "classification": annotation_values(g.annotations).get("classification", "")}
                    for n, g in sorted(view.schema.subsets.items())},
        "classes": {},
        "enums": {
            str(name): [str(value) for value in enum.permissible_values]
            for name, enum in sorted(enums.items())
        },
    }
    for name, cls in sorted(classes.items()):
        ancestors = [str(item) for item in view.class_ancestors(name)]
        record: dict[str, Any] = {
            "subsets": [str(n) for n in cls.in_subset],
            "abstract": bool(cls.abstract),
            "mixins": [str(x) for x in cls.mixins],
            "ancestors": ancestors,
            "description": cls.description or "",
            "annotations": annotation_values(cls.annotations),
            "slots": {},
            "rules": [
                rule
                for ancestor in reversed(ancestors)
                for rule in raw_model.get("classes", {}).get(ancestor, {}).get("rules", [])
            ],
        }
        if cls.is_a:
            record["is_a"] = str(cls.is_a)
        for slot in sorted(view.class_induced_slots(name), key=lambda item: item.name):
            if any(item.range is None for item in slot.any_of):
                raise ValueError(f"{name}.{slot.name}: catalog any_of requires explicit ranges")
            alternatives = [str(item.range) for item in slot.any_of]
            declared_range = str(slot.range or view.schema.default_range or "string")
            effective_ranges = alternatives or [declared_range]
            class_ranges = [item for item in effective_ranges if item in classes]
            # Identifier-less class values are embedded by LinkML convention.
            inlined = bool(slot.inlined or slot.inlined_as_list) or bool(
                class_ranges and all(view.get_identifier_slot(item) is None for item in class_ranges)
            )
            shape: dict[str, Any] = {
                "range": declared_range,
                "any_of": alternatives,
                "reference_ranges": [] if inlined else class_ranges,
                "inline_ranges": class_ranges if inlined else [],
                "required": bool(slot.required),
                "multivalued": bool(slot.multivalued),
                "inlined": inlined,
                "inlined_as_list": bool(slot.inlined_as_list),
                "ordered": bool(slot.list_elements_ordered),
                "identifier": bool(slot.identifier),
                "description": slot.description or "",
                "annotations": annotation_values(slot.annotations),
            }
            if declared_range in enums:
                shape["enum_values"] = result["enums"][declared_range]
            for field in (
                "equals_string", "pattern", "minimum_value", "maximum_value",
                "minimum_cardinality", "maximum_cardinality",
            ):
                value = getattr(slot, field)
                if value is not None:
                    shape[field] = value
            record["slots"][str(slot.name)] = shape
        result["classes"][str(name)] = record
    validate_groups(result)
    validate_annotations(result)
    validate_relationships(result)
    return result


def validate_annotations(catalog: dict[str, Any]) -> None:
    """Reject stale projection/ownership paths before they reach the CLI."""
    classes = catalog["classes"]

    def permits(actual: str, allowed: list[str]) -> bool:
        return any(parent in classes[actual]["ancestors"] for parent in allowed)

    for name, cls in classes.items():
        for annotation in ("projection_of", "owned_memberships"):
            expression = cls["annotations"].get(annotation)
            if not expression:
                continue
            for item in expression.split(" or "):
                source, separator, path = item.strip().partition(".")
                if not separator or source not in classes or not path:
                    raise ValueError(f"{name}.{annotation}: invalid model path {item!r}")
                current = source
                parts = path.split(".")
                for index, part in enumerate(parts):
                    slot = classes[current]["slots"].get(part)
                    if slot is None:
                        raise ValueError(f"{name}.{annotation}: absent field {current}.{part}")
                    if index < len(parts) - 1:
                        if slot["multivalued"] or len(slot["inline_ranges"]) != 1:
                            raise ValueError(f"{name}.{annotation}: intermediate field must be one embedded value")
                        current = slot["inline_ranges"][0]
                targets = slot["reference_ranges"]
                if not targets:
                    raise ValueError(f"{name}.{annotation}: final field must contain record references")
                if annotation == "projection_of":
                    subject = cls["slots"]["subject"]["reference_ranges"]
                    objects = cls["slots"]["object"]["reference_ranges"]
                    if not permits(source, subject) or not all(permits(target, objects) for target in targets):
                        raise ValueError(f"{name}.{annotation}: projection violates declared assertion endpoints")
                else:
                    if name not in classes[source]["ancestors"]:
                        raise ValueError(f"{name}.{annotation}: membership source must inherit its declaring class")
                    metadata = slot["annotations"]
                    if metadata.get("relationship_category") != "declaration-containment" or metadata.get("relationship_cycles") != "forbidden":
                        raise ValueError(f"{name}.{annotation}: membership must declare containment and forbid cycles")
                    for target in targets:
                        if f"{target}.owner" not in metadata.get("relationship_inverse", "").split(" or "):
                            raise ValueError(f"{name}.{annotation}: membership inverse must identify {target}.owner")
                        owner = classes[target]["slots"].get("owner", {})
                        if not permits(source, owner.get("reference_ranges", [])):
                            raise ValueError(f"{name}.{annotation}: {target}.owner does not permit {source}")


def escape(value: Any) -> str:
    return " ".join(str(value).split()).replace("|", "\\|")


def reference_markdown(catalog: dict[str, Any], raw_model: dict[str, Any]) -> bytes:
    """A complete lookup surface generated from the same induced-slot catalog."""
    lines = [
        "# Specification model reference", "",
        "Generated by `python scripts/generate-model/generate.py` from "
        "[the canonical LinkML model](../../../model/dotspec.yaml). Do not edit this file.", "",
        escape(raw_model["description"]), "",
        f"Model version: `{catalog['model_version']}`. "
        f"JSON representation version: `{catalog['representation_version']}`.", "",
        "The [JSON Schema](../../../model/generated/schema.json) checks local shape. "
        "The [runtime catalog](../../../model/generated/catalog.json) supplies inherited "
        "class membership, typed reference ranges and ordered slots for graph checks.", "",
        "See the [relationship reference](relationships.md) for scopes, inverses, cycle policies and assertion projections.", "",
        "## Model constraints", "",
        escape(catalog["annotations"].get("graph_rules", "")), "",
        "## Classes", "",
    ]
    lines[-2:] = subset_navigation(catalog) + ["## Classes", ""]
    for name, cls in catalog["classes"].items():
        lines += [f"### {name}", "", escape(cls["description"]), ""]
        lines += ["Subsets: " + ", ".join(f"`{s}`" for s in cls["subsets"]) + ".", ""]
        traits = ["Abstract" if cls["abstract"] else "Concrete"]
        if cls.get("mixins"):
            traits.append("capabilities " + ", ".join(f"[{m}](#{m.lower()})" for m in cls["mixins"]))
        if cls.get("is_a"):
            traits.append(f"inherits [{cls['is_a']}](#{cls['is_a'].lower()})")
        lines += ["; ".join(traits) + ".", ""]
        for key, value in cls["annotations"].items():
            lines += [f"**{escape(key)}:** {escape(value)}", ""]
        if cls["rules"]:
            lines += ["Conditional rules:", ""]
            for rule in cls["rules"]:
                lines.append(f"- {escape(rule.get('description', json.dumps(rule, sort_keys=True)))}")
            lines.append("")
        lines += ["| Field | Range | Shape | Meaning |", "| --- | --- | --- | --- |"]
        for slot_name, slot in cls["slots"].items():
            ranges = slot["any_of"] or [slot["range"]]
            display = " or ".join(
                f"[{item}](#{item.lower()})" if item in catalog["classes"] else f"`{item}`"
                for item in ranges
            )
            shape = ["required" if slot["required"] else "optional"]
            if slot["multivalued"]:
                shape.append("ordered list" if slot["ordered"] else "list")
            if slot["reference_ranges"]:
                shape.append("record ID")
            if slot["inlined"]:
                shape.append("embedded")
            if slot["identifier"]:
                shape.append("identifier")
            if "equals_string" in slot:
                shape.append(f"fixed `{slot['equals_string']}`")
            constraints = []
            for key in ("pattern", "minimum_value", "maximum_value", "minimum_cardinality", "maximum_cardinality"):
                if key in slot:
                    constraints.append(f"{key}=`{slot[key]}`")
            meaning = escape(slot["description"])
            if constraints:
                meaning += (" " if meaning else "") + "; ".join(escape(item) for item in constraints)
            lines.append(f"| `{slot_name}` | {display} | {', '.join(shape)} | {meaning} |")
        lines.append("")
    lines += ["## Enumerations", ""]
    for name, values in catalog["enums"].items():
        enum = raw_model.get("enums", {}).get(name, {})
        lines += [f"### {name}", "", escape(enum.get("description", "")), "",
                  "| Value | Meaning |", "| --- | --- |"]
        for value in values:
            meaning = enum.get("permissible_values", {}).get(value, {}) or {}
            lines.append(f"| `{value}` | {escape(meaning.get('description', ''))} |")
        lines.append("")
    return ("\n".join(lines).rstrip() + "\n").encode()


def generate_outputs() -> dict[Path, bytes]:
    # Imports follow the version check so setup errors remain actionable.
    import yaml
    from jsonschema import Draft202012Validator
    from linkml_runtime.utils.schemaview import SchemaView

    model_bytes = MODEL.read_bytes()
    raw_model = yaml.safe_load(model_bytes)
    view = SchemaView(str(MODEL))
    # Invoke the installed console-script callable through its interpreter.
    # Windows script locations/.exe wrappers differ; -m also re-executes this
    # module after LinkML's package imports it and emits a runpy warning.
    schema_bytes = subprocess.check_output([
        sys.executable, "-c", "from linkml.generators.jsonschemagen import cli; cli()",
        "--no-include-null", "--include-range-class-descendants",
        "--no-generation-date", str(MODEL),
    ]).replace(b"\r\n", b"\n").rstrip(b"\n") + b"\n"
    schema = json.loads(schema_bytes)
    Draft202012Validator.check_schema(schema)
    catalog = make_catalog(view, raw_model, model_bytes)
    view_definition = yaml.safe_load((ROOT / "model/views/core-domain.yaml").read_text())
    core_reference = core_markdown(catalog, view_definition)
    return {
        ROOT / "docs/reference/model/core.md": core_reference,
        ROOT / "docs/reference/model/relationships.md": relationships_markdown(catalog),
        ROOT / "model/generated/schema.json": schema_bytes,
        ROOT / "model/generated/catalog.json": (json.dumps(catalog, indent=2, sort_keys=True) + "\n").encode(),
        ROOT / "docs/reference/model/index.md": reference_markdown(catalog, raw_model),
    }


def sync_outputs(outputs: dict[Path, bytes], check: bool) -> list[Path]:
    stale = []
    for path, expected in outputs.items():
        if check:
            if not path.is_file() or path.read_bytes() != expected:
                stale.append(path)
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(expected)
    return stale


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="verify projections without writing files")
    args = parser.parse_args()
    try:
        verify_toolchain()
        outputs = generate_outputs()
        stale = sync_outputs(outputs, args.check)
    except (OSError, RuntimeError, ValueError, subprocess.CalledProcessError) as error:
        print(error, file=sys.stderr)
        return 1
    if stale:
        print("Generated model files are stale: " + ", ".join(str(path.relative_to(ROOT)) for path in stale)
              + "; run python scripts/generate-model/generate.py", file=sys.stderr)
        return 1
    print(("Verified" if args.check else "Generated") + f" {len(outputs)} model projections.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
